CREATE TABLE `price` (
  `price_id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date DEFAULT NULL,
  `premise_code` varchar(10) DEFAULT NULL,
  `item_code` varchar(9) DEFAULT NULL,
  `price` double DEFAULT NULL,
  PRIMARY KEY (`price_id`),
  KEY `idx_price_item_code` (`item_code`),
  KEY `idx_price_premise_code` (`premise_code`),
  CONSTRAINT `fk_price_item` FOREIGN KEY (`item_code`) REFERENCES `lookup_item` (`item_code`) ON UPDATE CASCADE,
  CONSTRAINT `fk_price_premise` FOREIGN KEY (`premise_code`) REFERENCES `lookup_premise` (`premise_code`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=268490 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 268489 rows for price

CREATE TABLE `price_catcher_item` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `item_code` varchar(9) NOT NULL,
  `item` varchar(255) NOT NULL,
  `unit` varchar(50) DEFAULT NULL,
  `item_group` varchar(100) DEFAULT NULL,
  `item_category` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pc_item_code` (`item_code`)
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 406 rows for price_catcher_item

CREATE TABLE `price_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `cost_price` float NOT NULL,
  `target_margin` float NOT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `price_history_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 12 rows for price_history

CREATE TABLE `product` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `cost_price` float NOT NULL,
  `target_margin` float NOT NULL,
  `category` varchar(80) DEFAULT NULL,
  `user_id` int(11) NOT NULL,
  `baseline_margin` double DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `product_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 10 rows for product

CREATE TABLE `user` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `email` varchar(120) NOT NULL,
  `password_hash` varchar(256) NOT NULL,
  `role` varchar(20) NOT NULL DEFAULT 'staff',
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

